    local pick = val("u_list", {})
    for _, name in ipairs(U.ORDER) do
        local k = U.KEY[name]
        if pick[name] then
            local cost = U.nextCost(k, s)
            if cost and (s.inf or pts >= cost) then
                local lv = (s.levels or {})[k]
                G.fire(G.SR, "BuyUpgrade", k)
                local t = os.clock()
                while os.clock() - t < 1 and (G.stats().levels or {})[k] == lv do task.wait(0.05) end
                return
            end
        end
    end
end
local W = { hl = setmetatable({}, { __mode = "k" }) }
function W.clearHL()
    for m, h in pairs(W.hl) do pcall(function() h:Destroy() end); W.hl[m] = nil end
end
function W.lastItems()
    local left = tonumber(Workspace:GetAttribute("LooseItemsLeft")) or 9999
    if not on("v_last") or left > (tonumber(val("v_last_n", 40)) or 40) then
        if next(W.hl) then W.clearHL() end
        return
    end
    for _, it in ipairs(F.loose(nil, nil, 80)) do
        if not W.hl[it.m] then
            local h = Instance.new("Highlight")
            h.FillColor = Color3.fromRGB(255, 200, 40)
            h.OutlineColor = Color3.new(1, 1, 1)
            h.FillTransparency = 0.35
            h.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
            h.Adornee = it.m
            h.Parent = it.m
            W.hl[it.m] = h
        end
    end
    for m, h in pairs(W.hl) do
        if not m.Parent or m.Parent.Name ~= "Items" then pcall(function() h:Destroy() end); W.hl[m] = nil end
    end
end
function W.bright(v)
    if v then
        W.saved = W.saved or { Lighting.Brightness, Lighting.ClockTime, Lighting.GlobalShadows, Lighting.Ambient }
        Lighting.Brightness = 2; Lighting.ClockTime = 14; Lighting.GlobalShadows = false; Lighting.Ambient = Color3.fromRGB(180, 180, 180)
    elseif W.saved then
        Lighting.Brightness, Lighting.ClockTime, Lighting.GlobalShadows, Lighting.Ambient = table.unpack(W.saved)
        W.saved = nil
    end
end
function W.gfx(v)
    if v then W.gfxOn = true elseif not W.gfxOn then return end
    pcall(function() settings().Rendering.QualityLevel = v and Enum.QualityLevel.Level01 or Enum.QualityLevel.Automatic end)
    for _, d in ipairs(Workspace:GetDescendants()) do
        if d:IsA("ParticleEmitter") or d:IsA("Trail") or d:IsA("Beam") then pcall(function() d.Enabled = not v end) end
    end
    if not v then W.gfxOn = nil end
end
local L = { party = nil, partyAt = 0, daily = nil, maps = { "Toy Store", "Pet Store", "Bakery", "Restaurant", "School", "Miniature", "Cinema" } }
L.KEY = { ["Toy Store"] = "toy", ["Pet Store"] = "pet", Bakery = "bakery", Restaurant = "restaurant", School = "school", Miniature = "miniature", Cinema = "cinema" }
function L.pads()
    local out = {}
    for _, c in ipairs(Workspace:GetChildren()) do
        if c.Name == "TeleportPart" and c:IsA("BasePart") then
            local busy = false
            for _, g in ipairs(c:GetChildren()) do
                if g:IsA("BillboardGui") and g.Name == "PadCount" then
                    for _, t in ipairs(g:GetDescendants()) do
                        if t:IsA("TextLabel") and t.Text:find("%d+/%d+") then busy = true end
                        if t:IsA("TextLabel") and t.Text:lower():find("creat") then busy = true end
                    end
                end
            end
            table.insert(out, { part = c, busy = busy })
        end
    end
    return out
end
function L.start()
    if L.busy then return end
    L.busy = true
    task.spawn(function()
        local ok = pcall(function()
            local key = L.KEY[val("l_map", "Toy Store")] or "toy"
            local P = L.party
            if P and P.isHost and P.padId and not P.closed then
                if P.map ~= key or not P.mapPicked then G.fire(G.LR, "PartyAction", P.padId, "map", key); task.wait(1) end
                if val("l_mode", "Normal") == "Hard" and P.mode ~= "hard" then G.fire(G.LR, "PartyAction", P.padId, "mode", "hard"); task.wait(0.8) end
                if L.beforeStart then pcall(L.beforeStart) end
                G.fire(G.LR, "PartyAction", P.padId, "start")
                S.task = "Starting store"
                task.wait(4)
                return
            end
            if P and not P.closed and P.members and not P.isHost then
                G.fire(G.LR, "PartyAction", "leave"); G.fire(G.LR, "LeavePad"); task.wait(1)
            end
            for _, pd in ipairs(L.pads()) do
                if not pd.busy then
                    L.party = nil
                    tp(pd.part.Position + Vector3.new(0, 3, 0))
                    local t = os.clock()
                    while not L.party and os.clock() - t < 4 do task.wait(0.1) end
                    local Q = L.party
                    if Q and Q.isHost and #(Q.members or {}) == 1 then return end
                    if Q then G.fire(G.LR, "PartyAction", "leave"); G.fire(G.LR, "LeavePad"); task.wait(0.8) end
                end
            end
            S.task = "No free pad"
            task.wait(3)
        end)
        L.busy = false
    end)
end
function L.claimDaily()
    local d = L.daily
    if type(d) ~= "table" or type(d.quests) ~= "table" then return end
    for _, q in ipairs(d.quests) do
        if not q.claimed and (tonumber(q.progress) or 0) >= (tonumber(q.goal) or 1) and (not q.vip or d.vip) then
            G.fire(G.LR, "DailyClaim", q.claimKey)
            q.claimed = true
            task.wait(0.6)
        end
    end
end
local LP = { file = "COMBO_WICK_CINEMA/loop.json" }
function LP.read()
    local ok, d = pcall(function() return HttpService:JSONDecode(readfile(LP.file)) end)
    return ok and type(d) == "table" and d or {}
end
function LP.write(d)
    pcall(function()
        if not isfolder("COMBO_WICK_CINEMA") then makefolder("COMBO_WICK_CINEMA") end
        writefile(LP.file, HttpService:JSONEncode(d))
    end)
end
function LP.save()
    LP.write({ on = on("lp_on") == true, map = val("l_map", "Toy Store"), mode = val("l_mode", "Normal"), upg = val("u_list", {}), delay = val("f_delay", 0.12) })
end
function LP.queue()
    local src = (CONFIG.LOADER ~= "" and CONFIG.LOADER) or 'if isfile and isfile("cinema_hub.lua") then loadstring(readfile("cinema_hub.lua"))() end'
    local q = queue_on_teleport or queueonteleport or (syn and syn.queue_on_teleport)
    if q then pcall(q, src) end
end
L.beforeStart = function() LP.save(); LP.queue() end
function LP.finish()
    if LP.busy then return end
    LP.busy = true
    LP.save()
    LP.queue()
    S.task = "Store done · next store"
    task.wait(3)
    if LP.ascend then G.fire(G.SR, "Ascend") end
    task.wait(8)
    pcall(function() game:GetService("TeleportService"):Teleport(140576663170542, lp) end)
    task.wait(15)
    LP.busy = false
end
